import React, { useEffect, useState } from 'react';
import api from '../api/axios';
import { Container, Row, Col, Card, Image } from 'react-bootstrap';

const Teachers = () => {
  const [teachers, setTeachers] = useState([]);

  useEffect(() => {
    const fetchTeachers = async () => {
      const res = await api.get('/director/teachers'); // маршрут надо добавить
      setTeachers(res.data);
    };
    fetchTeachers();
  }, []);

  return (
    <Container className="mt-4">
      <h2>Учителя</h2>
      <Row>
        {teachers.map(teacher => (
          <Col md={4} key={teacher.id} className="mb-3">
            <Card>
              <Image src={`http://localhost:8080/uploads/${teacher.avatar}`} roundedCircle />
              <Card.Body>
                <Card.Title>{teacher.last_name} {teacher.first_name} {teacher.middle_name}</Card.Title>
                <Card.Text>{teacher.position}</Card.Text>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default Teachers;
